mapper.sql:
WHERE 1=1

	 AND (CASE 팝업사용 WHEN 'Y' THEN #{searchDtFrom}  ELSE 공지시작일자 END ) >= #{searchDtFrom} 


	 AND (CASE 팝업사용 WHEN 'Y' THEN #{searchDtTo}  ELSE 공지시작일자 END ) <= #{searchDtTo} 


	 AND (제목 LIKE UPPER('%'+ #{searchTitle} +'%')
				OR 내용 LIKE UPPER('%'+ #{searchTitle} +'%'))

mapper.update:
UPDATE 웹공지사항 SET
	공지시작일자 = #{noticeDtFrom}
	, 공지종료일자 = #{noticeDtTo}
	, 제목 = #{noticeTitle}
	, 내용 = #{noticeCn}
	, 수정자 = #{register}
	, 수정일자 = CONVERT(VARCHAR,GETDATE(),112)
	, 수정시간 = REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','')
WHERE 일련번호 = #{ID}

UPDATE 웹공지사항 SET
	 표시유무 = #{noticeAt}
	, 수정자 = #{register}
	, 수정일자 = CONVERT(VARCHAR,GETDATE(),112)
	, 수정시간 = REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','')
WHERE 일련번호 = #{ID}
